// src/calculators/InternetCalculator.jsx
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { internetConfig } from '../config/config';

export default function InternetCalculator() {
  const navigate = useNavigate();
  const [nameQuery, setNameQuery] = useState('');
  const [speedQuery, setSpeedQuery] = useState('');
  const [selected, setSelected] = useState(null);

  // nameQuery 혹은 speedQuery 입력이 있으면 필터링
  const filteredPlans = internetConfig.plans.filter(p => {
    const nameMatch =
      nameQuery === '' ||
      p.name.toLowerCase().includes(nameQuery.toLowerCase());
    const speedMatch =
      speedQuery === '' ||
      p.speed.toLowerCase().includes(speedQuery.toLowerCase());
    // 둘 다 만족하는 항목만
    return nameMatch && speedMatch;
  });

  return (
    <div className="p-6 max-w-3xl mx-auto">
      {/* 타이틀 */}
      <h1 className="text-3xl font-bold mb-8 text-center">
        KT 인터넷 계산기
      </h1>

      {/* 검색 폼 */}
      <div className="space-y-6 mb-8">
        {/* 명칭 검색 */}
        <div>
          <label className="block mb-1 font-medium">
            인터넷 명칭으로 검색
          </label>
          <input
            type="text"
            value={nameQuery}
            onChange={e => {
              setNameQuery(e.target.value);
              setSelected(null);      // 검색 변경 시 선택 초기화
            }}
            placeholder="예) 인터넷 슈퍼프리미엄"
            className="w-full border rounded p-2"
          />
        </div>

        {/* 속도 검색 */}
        <div>
          <label className="block mb-1 font-medium">
            인터넷 속도로 검색
          </label>
          <input
            type="text"
            value={speedQuery}
            onChange={e => {
              setSpeedQuery(e.target.value);
              setSelected(null);
            }}
            placeholder="예) 500Mbps, 1Gbps 등"
            className="w-full border rounded p-2"
          />
        </div>
      </div>

      {/* 검색 결과 리스트 */}
      {(nameQuery || speedQuery) && filteredPlans.length > 0 && (
        <ul className="mb-8 border rounded overflow-hidden">
          {filteredPlans.map(plan => (
            <li
              key={plan.id}
              onClick={() => setSelected(plan)}
              className="flex justify-between px-4 py-2 hover:bg-gray-100 cursor-pointer"
            >
              <span>{plan.name}</span>
              <span className="text-sm text-gray-500">({plan.speed})</span>
            </li>
          ))}
        </ul>
      )}

      {/* 선택된 플랜 가격표 */}
      {selected && (
        <table className="w-full table-auto border-collapse mb-8">
          <thead>
            <tr className="bg-gray-100">
              <th className="border px-3 py-2">속도</th>
              {Object.keys(selected.pricing).map(term => (
                <th key={term} className="border px-3 py-2">
                  {term}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            <tr>
              <td className="border px-3 py-2">{selected.speed}</td>
              {Object.values(selected.pricing).map((price, i) => (
                <td key={i} className="border px-3 py-2">
                  {price.toLocaleString()}원
                </td>
              ))}
            </tr>
          </tbody>
        </table>
      )}

      {/* 메인으로 돌아가기 */}
      <button
        type="button"
        onClick={() => navigate('/')}
        className="block mx-auto bg-gray-200 text-gray-700 rounded py-2 px-4 hover:bg-gray-300 transition"
      >
        메인으로 돌아가기
      </button>
    </div>
  );
}
